#include "backup_policy.h"
#include <assert.h>
#include <stdlib.h>
static unsigned erases,writes;static bool fail_write;static uint8_t memory[32768];
static bool erase(void *ctx,size_t at,size_t n){assert(ctx==memory&&at+n<=sizeof(memory));memset(memory+at,255,n);erases++;return true;}
static bool write(void *ctx,size_t at,const void *b,size_t n){assert(ctx==memory&&at+n<=sizeof(memory));if(fail_write)return false;memcpy(memory+at,b,n);writes++;return true;}
int main(void){assert(backup_crc(0,"123456789",9)==0xcbf43926);assert(backup_crc(backup_crc(0,"1234",4),"56789",5)==0xcbf43926);assert(!backup_chunk_valid(32768,32768,4096));assert(!backup_chunk_valid(32768,1,4096));assert(!backup_chunk_valid(32768,0,16385));assert(!backup_chunk_valid(32768,0,0));uint8_t data[16384];for(unsigned i=0;i<sizeof(data);i++)data[i]=i;track_io_t io={.context=memory,.erase=erase,.write=write};uint32_t next=0,crc=backup_crc(0,data,sizeof(data));assert(!backup_apply_chunk(io,sizeof(memory),0,sizeof(data),0,data,crc^1,&next)&&!erases);assert(!backup_apply_chunk(io,sizeof(memory),16384,sizeof(data),0,data,crc,&next)&&!erases);fail_write=true;assert(!backup_apply_chunk(io,sizeof(memory),0,sizeof(data),0,data,crc,&next));assert(next==0);fail_write=false;assert(backup_apply_chunk(io,sizeof(memory),0,sizeof(data),0,data,crc,&next)&&next==16384);assert(backup_apply_chunk(io,sizeof(memory),0,sizeof(data),next,data,crc,&next)&&next==16384);assert(backup_apply_chunk(io,sizeof(memory),16384,sizeof(data),next,data,crc,&next)&&next==32768);assert(!memcmp(memory,data,sizeof(data))&&!memcmp(memory+16384,data,sizeof(data)));char hex[33];uint8_t output[16];backup_hex_encode(data,16,hex);assert(backup_hex_decode(hex,output,16)&&!memcmp(output,data,16));assert(!backup_hex_decode("xyz",output,1));return 0;}
